SELECT os,
       SUM(cnt) AS count
FROM t_link_os_stats
WHERE full_short_url = #{fullShortUrl}
  AND gid = #{gid}
  AND date BETWEEN #{startDate} AND #{endDate}
  AND del_flag = 0
GROUP BY full_short_url, gid, os;

SELECT os,
       SUM(cnt) AS count
FROM t_link_os_stats
WHERE gid = #{gid}
  AND date BETWEEN #{startDate} and #{endDate}
GROUP BY gid, os;
